#!/usr/bin/env bash
# qa-verifier r7 (round-3 harness, ports moved): copy the probe into the disposable clone, run it alone on a disposable PostgreSQL, remove it.
set -u
C=$TMPDIR/review-qa; E=/home/user/My-owns/docs/delivery/test-evidence/DG5/qa/round-7; T=/home/user/My-owns/docs/delivery/test-evidence/DG5/qa/tests/round-2
export PATH=/opt/nvm/versions/node/v24.21.0/bin:$PATH
F=zz-qa-dg5r2-packs-provisional-samples.test.ts; LBL=${1:-run1}
cp $T/integration/$F $C/tests/qa/integration/$F; cd $C
mkdir -p $E/samples
L=$E/06-probe-packs-provisional-$LBL.log
{ echo "\$ QA_SAMPLES_DIR=<evidence>/samples QA_PG_PORT=26660 MTH_PORT_POOL=26600-26699 tests/qa/support/with-pg.sh npx vitest run --project integration tests/qa/integration/$F  (node $(node -v), $(date -u +%FT%TZ))"; uptime
QA_SAMPLES_DIR=$E/samples QA_PG_PORT=26660 MTH_PORT_POOL=26600-26699 tests/qa/support/with-pg.sh npx vitest run --project integration tests/qa/integration/$F 2>&1 | sed "s#$TMPDIR#\$TMPDIR#g; s#$E#<evidence>#g"
echo "EXIT ${PIPESTATUS[0]}"; date -u +%FT%TZ; } > $L 2>&1
rm -f $C/tests/qa/integration/$F
sed 's/\x1b\[[0-9;]*m//g' $L | grep -E "Test Files|Tests |^EXIT|✓|×"
#!/usr/bin/env bash
# qa-verifier r7: the A06/A07/A15/A16 executable suites (tests/qa/integration) per integration log: file result line.
for L in "$@"; do echo "== $(basename $L)"; sed 's/\x1b\[[0-9;]*m//g' $L | grep -E "^ (✓|❯|×) \|integration\| tests/qa/integration/(a06|a07|a15|a16)-" | sed 's/ [0-9]*ms$//'; done
// qa-verifier r3: import every p5-pending-*.ts (Node 24 type stripping) and print the size of each exported collection.
import { execSync } from "node:child_process";
import { pathToFileURL } from "node:url";
const files = execSync("find . -name 'p5-pending-*.ts' -not -path '*/node_modules/*' | sort").toString().trim().split("\n");
let nonEmpty = 0;
for (const f of files) {
  const m = await import(pathToFileURL(f).href);
  const sizes = Object.entries(m).map(([k, v]) => [k, v instanceof Set || v instanceof Map ? v.size : Array.isArray(v) ? v.length : typeof v === "object" && v ? Object.keys(v).length : String(v)]);
  for (const [, s] of sizes) if (typeof s === "number" && s > 0) nonEmpty++;
  console.log(f, JSON.stringify(sizes));
}
console.log(`files=${files.length} non-empty exports=${nonEmpty}`);

