        .map((x) => `${x.el.tagName.toLowerCase()}.${(x.el.getAttribute("class") ?? "").trim().split(/\s+/).join(".")} scrollWidth ${x.sw} clientWidth ${x.cw}`);
      const table = card.querySelector<HTMLElement>("table");
