      if (c[0]! < -1 || c[1]! > m.W + 1) failures.push(`${label}: outcome card ${i} outside the viewport ${JSON.stringify(c)}`);
    });
    if (m.tables.length < 2) failures.push(`${label}: set-up, expected 2 Good-outcome tables, found ${m.tables.length}`);
